'use client';

import * as React from "react";
import type { Framework, ExampleCardData } from "./types";
import { PRODUCT_URLS } from "./types";

type CardProps = ExampleCardData;

const FrameworkIcon = ({ framework }: { framework: Framework }) => {
  switch (framework) {
    case "Next.js":
      return (
        <span className="wf-framework-icon card-icon">
          <img 
            src="https://files.buildwithfern.com/https://webflow.docs.buildwithfern.com/2025-06-06T16:08:34.749Z/products/webflow-cloud/pages/introduction/assets/nextjs-dark.svg"
            alt="Next.js"
            className="mx-auto dark-icon" 
          />
          <img 
            src="https://files.buildwithfern.com/https://webflow.docs.buildwithfern.com/2025-06-06T16:08:34.749Z/products/webflow-cloud/pages/introduction/assets/nextjs.svg"
            alt="Next.js"
            className="mx-auto light-icon" 
          />
        </span>
      );
    case "Astro":
      return (
        <span className="wf-framework-icon">
          <img 
            src="https://astro.build/assets/press/astro-icon-light.svg" 
            alt="Astro" 
            className="dark-icon" 
          />
          <img 
            src="https://astro.build/assets/press/astro-icon-dark.svg" 
            alt="Astro" 
            className="light-icon" 
          />
        </span>
      );
    case "Svelte":
      return (
        <span className="wf-framework-icon">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M19.229 4.1458C17.8119 2.1249 14.9624 1.56161 12.5416 2.67583L7.76902 5.12583C6.55902 5.75083 5.63402 6.80083 5.17152 8.06333C4.83402 9.00083 4.79652 10.0133 5.06402 10.9708C4.81402 11.3458 4.61902 11.7583 4.48402 12.1933C4.02152 13.4558 3.98402 14.8433 4.37902 16.1433C5.79152 20.1808 10.1665 22.0133 14.204 20.6008L18.979 18.1508C20.189 17.5258 21.114 16.4758 21.5765 15.2133C22.039 13.9508 22.0765 12.5633 21.6815 11.2633C21.5465 10.8283 21.354 10.4158 21.104 10.0408C21.3715 9.08333 21.334 8.07083 20.9965 7.13333C20.534 5.87083 19.979 4.87583 19.229 4.1458Z" fill="currentColor"/>
          </svg>
        </span>
      );
    default:
      return null;
  }
};

export const ExampleCard = ({ 
  title, 
  description, 
  liveUrl,
  repoUrl,
  image, 
  imageAlt,
  products,
  framework
}: CardProps) => (
  <div className="wf-card">
    <div className="wf-card-image-container">
      {image ? (
        <>
          <img 
            src={image} 
            alt={imageAlt || title} 
            className="wf-card-image"
          />
          <div className="wf-card-image-overlay" />
        </>
      ) : (
        <img 
          src="https://dhygzobemt712.cloudfront.net/Logo/Social_Circle_Blue.svg"
          alt="Webflow Logo"
          className="default-logo"
        />
      )}
    </div>
    <div className="wf-card-metadata">
      <div className="wf-card-content">
        <div className="wf-card-text">
          {products && products.length > 0 && (
            <div className="wf-product-tags">
              {products.map((product, index) => (
                <a 
                  key={index} 
                  href={PRODUCT_URLS[product]}
                  className="wf-product-tag"
                >
                  {product}
                </a>
              ))}
            </div>
          )}
          <h2 className="wf-card-title">{title}</h2>
          <p className="wf-card-description">{description}</p>
        </div>
        {framework && <FrameworkIcon framework={framework} />}
      </div>
    </div>
    <div className="wf-card-actions">
      {liveUrl && (
        <a 
          href={liveUrl}
          className="wf-card-button wf-card-button-primary"
          target="_blank"
          rel="noopener noreferrer"
        >
          Live Example
        </a>
      )}
      {repoUrl && (
        <a 
          href={repoUrl}
          className="wf-card-button wf-card-button-secondary"
          target="_blank"
          rel="noopener noreferrer"
        >
          View Code
        </a>
      )}
    </div>
  </div>
);

