'use client';

import * as React from "react";
import { ExampleCard } from "./Card";
import type { ExampleCardData } from "./types";

interface ExampleCardGroupProps {
  cards: ExampleCardData[];
  columns?: 1 | 2 | 3 | 4;
}

export const ExampleCardGroup = ({ 
  cards, 
  columns = 2 
}: ExampleCardGroupProps) => {
  const gridCols = {
    1: "grid-cols-1",
    2: "grid-cols-1 sm:grid-cols-2",
    3: "grid-cols-1 sm:grid-cols-2 lg:grid-cols-3",
    4: "grid-cols-1 sm:grid-cols-2 lg:grid-cols-4"
  };

  return (
    <div className={`my-6 grid gap-4 sm:gap-6 ${gridCols[columns]}`}>
      {cards.map((card, idx) => (
        <ExampleCard key={idx} {...card} />
      ))}
    </div>
  );
};

