'use client';

import * as React from "react";
import type { DeveloperProduct, Framework } from './types';

interface FilterProps {
  onFilterChange?: (product: DeveloperProduct | null, framework: Framework | null) => void;
  initialProduct?: DeveloperProduct | null;
  initialFramework?: Framework | null;
}

const SelectContainer = ({ 
  value, 
  onChange, 
  options,
  label,
  disabled = false
}: { 
  value: string, 
  onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void,
  options: Array<{ value: string, label: string }>,
  label: string,
  disabled?: boolean
}) => (
  <div className="wf-filter-select-container">
    <select
      value={value}
      onChange={onChange}
      aria-label={label}
      className="wf-filter-select"
      disabled={disabled}
    >
      {options.map(option => (
        <option key={option.value} value={option.value}>
          {option.label}
        </option>
      ))}
    </select>
  </div>
);

const productOptions = [
  { value: '', label: 'All Products' },
  { value: 'Webflow Cloud', label: 'Webflow Cloud' },
  { value: 'Designer Extension', label: 'Designer Extension' },
  { value: 'Data Client', label: 'Data Client' },
];

// Define available frameworks for each product
const productFrameworks: Record<DeveloperProduct, Framework[]> = {
  'Webflow Cloud': ['Next.js', 'Astro'],
  'Designer Extension': ['Next.js', 'Svelte'],
  'Data Client': ['Next.js', 'Astro', 'Svelte'],
};

// Base framework options that will be filtered based on product selection
const allFrameworkOptions = [
  { value: '', label: 'All Frameworks' },
  { value: 'Next.js', label: 'Next.js' },
  { value: 'Astro', label: 'Astro' },
  { value: 'Svelte', label: 'Svelte' }
];

export function ExampleFilters({ 
  onFilterChange, 
  initialProduct = null, 
  initialFramework = null 
}: FilterProps) {
  const [product, setProduct] = React.useState<DeveloperProduct | null>(initialProduct);
  const [framework, setFramework] = React.useState<Framework | null>(initialFramework);

  // Get available framework options based on selected product
  const availableFrameworkOptions = React.useMemo(() => {
    if (!product) {
      return allFrameworkOptions;
    }

    const availableFrameworks = productFrameworks[product];
    return [
      allFrameworkOptions[0], // Include only the first "All Frameworks" option
      ...allFrameworkOptions
        .slice(1) // Skip the "All Frameworks" option from base array
        .filter(option => availableFrameworks.includes(option.value as Framework))
    ];
  }, [product]);

  // Update local state when initial values change
  React.useEffect(() => {
    setProduct(initialProduct);
  }, [initialProduct]);

  React.useEffect(() => {
    setFramework(initialFramework);
  }, [initialFramework]);

  const handleProductChange = React.useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
    const newProduct = e.target.value as DeveloperProduct | '';
    const newProductValue = newProduct || null;

    // Reset framework if it's not available for the new product
    let newFramework = framework;
    if (newProductValue && framework) {
      const availableFrameworks = productFrameworks[newProductValue];
      if (!availableFrameworks.includes(framework)) {
        newFramework = null;
      }
    }

    setProduct(newProductValue);
    setFramework(newFramework);
    onFilterChange?.(newProductValue, newFramework);
  }, [framework, onFilterChange]);

  const handleFrameworkChange = React.useCallback((e: React.ChangeEvent<HTMLSelectElement>) => {
    const newFramework = e.target.value as Framework | '';
    const newFrameworkValue = newFramework || null;

    setFramework(newFrameworkValue);
    onFilterChange?.(product, newFrameworkValue);
  }, [product, onFilterChange]);

  return (
    <div className="wf-filters-container">
      <SelectContainer
        value={product || ''}
        onChange={handleProductChange}
        options={productOptions}
        label="Filter by product"
      />
      <SelectContainer
        value={framework || ''}
        onChange={handleFrameworkChange}
        options={availableFrameworkOptions}
        label="Filter by framework"
      />
    </div>
  );
}

