'use client';

import * as React from "react";
import { ExampleCard } from './Card';
import type { ExampleCardData, DeveloperProduct } from './types';
import { ExampleFilters } from './ExampleFilters';

declare const window: Window & typeof globalThis;

type Example = ExampleCardData;

interface ExamplesContainerProps {
  examples: Example[];
}

// Map URL path segments to product filters
const getInitialProductFromPath = (): DeveloperProduct | null => {
  if (typeof window === 'undefined') return null;

  const pathParts = window.location.pathname.split('/');
  // Find the relevant path segment by looking for known product paths
  const productPath = pathParts.find(part => 
    ['webflow-cloud', 'designer', 'data'].includes(part)
  );

  const productMap: Record<string, DeveloperProduct> = {
    'webflow-cloud': 'Webflow Cloud',
    'designer': 'Designer Extension',
    'data': 'Data Client'
  };

  return productMap[productPath || ''] || null;
};

export function ExamplesContainer({ examples }: ExamplesContainerProps) {
  // Set initial product filter based on current path
  const [selectedProduct, setSelectedProduct] = React.useState<DeveloperProduct | null>(null);
  const [selectedFramework, setSelectedFramework] = React.useState<Example['framework'] | null>(null);

  // Auto-filter based on path on mount
  React.useEffect(() => {
    const initialProduct = getInitialProductFromPath();
    if (initialProduct) {
      setSelectedProduct(initialProduct);
    }
  }, []);

  // Filter examples based on selected filters
  const filteredExamples = React.useMemo(() => {
    return examples.filter(example => {
      const matchesProduct = !selectedProduct || (example.products && example.products.includes(selectedProduct));
      const matchesFramework = !selectedFramework || example.framework === selectedFramework;
      return matchesProduct && matchesFramework;
    });
  }, [examples, selectedProduct, selectedFramework]);

  const handleFilterChange = React.useCallback((product: DeveloperProduct | null, framework: Example['framework'] | null) => {
    setSelectedProduct(product);
    setSelectedFramework(framework);
  }, []);

  const handleResetFilters = React.useCallback(() => {
    setSelectedProduct(null);
    setSelectedFramework(null);
    handleFilterChange?.(null, null);
  }, [handleFilterChange]);

  return (
    <div className="wf-examples-container" style={{ maxWidth: '1200px', margin: '0 auto' }}>
      <div className="wf-examples-header">
        <a 
          href="https://github.com/Webflow-Examples"
          target="_blank"
          rel="noopener noreferrer"
          className="wf-github-button"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
            <path d="M12 0C5.374 0 0 5.373 0 12c0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23A11.509 11.509 0 0112 5.803c1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576C20.566 21.797 24 17.3 24 12c0-6.627-5.373-12-12-12z"/>
          </svg>
          See all examples on GitHub
        </a>
        <ExampleFilters 
          onFilterChange={handleFilterChange}
          initialProduct={selectedProduct}
          initialFramework={selectedFramework}
        />
      </div>
      {filteredExamples.length > 0 ? (
        <div className="wf-examples-grid">
          {filteredExamples.map((example, index) => (
            <ExampleCard
              key={index}
              {...example}
            />
          ))}
        </div>
      ) : (
        <div className="wf-examples-empty">
          <p>No examples found for the selected filters.</p>
          <button 
            onClick={handleResetFilters}
            className="wf-button wf-button-secondary"
          >
            Reset Filters
          </button>
        </div>
      )}
    </div>
  );
}

