  color: #A6A6A6;
}

.wf-filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.wf-filters-container {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-direction: row;
  flex-wrap: nowrap;
}

.wf-filter-select-container {
  margin-right: 1rem;
}

.wf-filter-select {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  padding: 0.75rem 1rem;
  padding-right: 2.5rem;
  border-radius: 6px;
  border: 1px solid #D8D8D8;
  background-color: #F0F0F0;
  font-size: 14px;
  font-weight: 500;
  min-width: 200px;
  color: #363636;
  cursor: pointer;
  transition: all 0.2s ease-in-out;
  background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5 5L9 1' stroke='%23363636' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 1rem center;
}

.wf-filter-select:hover {
  border-color: #146EF5;
  background-color: #F5F5F5;
}

.wf-filter-select:focus {
  outline: none;
  border-color: #146EF5;
  box-shadow: 0 0 0 2px rgba(20, 110, 245, 0.1);
  background-color: #F5F5F5;
}

:is(.dark) .wf-filter-select {
  background-color: #171717;
  border: 1px solid #146EF5;
  color: #FFFFFF;
  background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5 5L9 1' stroke='%23FFFFFF' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

:is(.dark) .wf-filter-select:hover {
  border-color: #146EF5;
  background-color: #222222;
}

:is(.dark) .wf-filter-select:focus {
  border-color: #146EF5;
  box-shadow: 0 0 0 2px rgba(20, 110, 245, 0.2);
  background-color: #222222;
}

@media (max-width: 768px) {
  .wf-filters-container {
    flex-direction: column;
    align-items: stretch;
  }

  .wf-filter-select-container {
    margin-right: 0;
    margin-bottom: 1rem;
  }

  .wf-filter-select {
    width: 100%;
  }
}

/* Examples Grid */
.wf-examples-container {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  padding-top: 2rem;
  width: 100%;
}

.wf-examples-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 2rem;
  flex-wrap: wrap;
  width: 100%;
  margin-bottom: 2rem;
}

.wf-github-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-radius: 6px;
  background-color: #F0F0F0;
  color: #222222;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.2s ease-in-out;
}

.wf-github-button:hover {
  background-color: #E6E6E6;
}

:is(.dark) .wf-github-button {
  background-color: #222222;
  color: #ABABAB;
}

:is(.dark) .wf-github-button:hover {
  background-color: #363636;
  color: #FFFFFF;
}

.wf-examples-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(320px, 1fr));
  gap: 2rem;
  width: 100%;
}

@media (max-width: 768px) {
  .wf-examples-grid {
    grid-template-columns: 1fr;
  }
}

.wf-examples-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 4rem 2rem;
  background: #F0F0F0;
  border-radius: 8px;
  margin-top: 2rem;
}

:is(.dark) .wf-examples-empty {
  background: #222222;
}

.wf-examples-empty p {
  font-size: 1.125rem;
  color: #5A5A5A;
  margin-bottom: 1.5rem;
}

:is(.dark) .wf-examples-empty p {
  color: #ABABAB;
}

.wf-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  font-size: 1rem;
  font-weight: 500;
  transition: all 0.2s ease-in-out;
  cursor: pointer;
  border: none;
}

.wf-button-secondary {
  background: #FFFFFF;
  color: #363636;
  border: 1px solid #D8D8D8;
}

.wf-button-secondary:hover {
  background: #F5F5F5;
  border-color: #ABABAB;
}

:is(.dark) .wf-button-secondary {
  background: #171717;
  color: #FFFFFF;
  border-color: #363636;
}

:is(.dark) .wf-button-secondary:hover {
  background: #222222;
  border-color: #146EF5;
}
